CREATE TABLE IF NOT EXISTS retailers(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,address TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS retailer_phones(id INTEGER PRIMARY KEY AUTOINCREMENT,retailer_id INTEGER NOT NULL REFERENCES retailers(id) ON DELETE CASCADE,phone TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,name TEXT,rate REAL DEFAULT 0,updated_at TEXT);
CREATE TABLE IF NOT EXISTS rate_history(id INTEGER PRIMARY KEY AUTOINCREMENT,product_id TEXT,rate REAL,date TEXT);
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY AUTOINCREMENT,retailer_id INTEGER,phone TEXT,wa_msg_id TEXT UNIQUE,status TEXT DEFAULT 'pending',created_at TEXT DEFAULT CURRENT_TIMESTAMP,delivered_at TEXT);
CREATE TABLE IF NOT EXISTS order_items(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL,product_id TEXT,name TEXT,qty REAL,rate REAL);
CREATE INDEX IF NOT EXISTS i_phone ON retailer_phones(phone);
CREATE INDEX IF NOT EXISTS i_items ON order_items(order_id);
